export const translations = {};
const { p, makeStory } = createStoryKit(translations);
export const stories = {},
  sources = {},
  profiles = {};
export const additions = { cambrian: [], carboniferous: [], jurassic: [] };
function add(key, species, time, note, endings, source, rows) {
  const era = key.split("-")[0];
  additions[era].push(species.map((x, i) => (i === 1 ? x : p(x))));
  stories[key] = makeStory(species[0], time, note, endings, rows);
  sources[key] = { ...source, checked: "2026-10-23" };
}
